package com.honorablemobile

import org.junit.runner.RunWith
import org.robolectric.RobolectricTestRunner
import org.robolectric.annotation.Config

import android.app.AlertDialog
import android.net.Uri
import app.honorable.editor.EditorAccessMode
import org.junit.Assert.*
import org.junit.Test

/** Real visible-approval/project mutation gates, with metadata-only dialog membership. */
@RunWith(RobolectricTestRunner::class)
@Config(sdk = [34], manifest = Config.NONE, application = android.app.Application::class)
class VideoBatchReviewOwnershipTest {
 private val unsafe=JvmTestAllocator
 private fun set(a:Any,n:String,v:Any?)=a.javaClass.getDeclaredField(n).apply{isAccessible=true}.set(a,v)
 private fun get(a:Any,n:String)=a.javaClass.getDeclaredField(n).apply{isAccessible=true}.get(a)
 private fun call(a:Any,n:String,vararg args:Any?)=a.javaClass.declaredMethods.single{it.name==n&&it.parameterCount==args.size}.apply{isAccessible=true}.invoke(a,*args)
 private fun activity()=(unsafe.allocateInstance(HonorableVideoEditorActivity::class.java)as HonorableVideoEditorActivity).also{val p=VideoEditProject(5000);p.restore(listOf(VideoSegment(0,5000,captions=listOf(VideoCaption(0,500,"A"),VideoCaption(1000,1500,"B")),captionSourceUri="content://synthetic/subtitles")),soundtrack=VideoSoundtrack("content://synthetic/music",10000,loop=false));set(it,"project",p);set(it,"source",Uri.parse("content://synthetic/video"));set(it,"primaryDurationMs",5000L);set(it,"accessMode",EditorAccessMode.GUEST_BASIC);set(it,"workspaceActive",true);set(it,"importedSources",linkedMapOf<String,VideoSource>())}
 private fun showing(d:AlertDialog,value:Boolean){android.app.Dialog::class.java.getDeclaredField("mDecor").apply{isAccessible=true}.set(d,if(value)unsafe.allocateInstance(android.view.View::class.java)else null)}
 private fun dialog()=(unsafe.allocateInstance(AlertDialog::class.java)as AlertDialog).also{showing(it,true)}
 private fun capture(a:HonorableVideoEditorActivity)=call(a,"captureCaptionReview")as VideoCaptionReviewState
 private fun project()=VideoEditProject(5000).also{it.restore(listOf(VideoSegment(0,5000,title="A",captions=listOf(VideoCaption(0,500,"Old")),captionSourceUri="content://synthetic/srt")),soundtrack=VideoSoundtrack("content://synthetic/music",10000))}
 private fun changed(p:VideoEditProject)=p.segments.map{it.copy(title="Batch")}
 private fun rejects(action:()->Unit){try{action();fail("Expected refusal")}catch(_:IllegalArgumentException){}}
 @Test fun advancingStageRejectsOldCallbacksAndLateDismiss(){val p=project();val r=VideoBatchReview(p.segments,p.soundtrack);val old=Any();val current=Any();assertTrue(r.open(old));assertTrue(r.open(current));r.dismiss(old);assertFalse(r.owns(old));assertTrue(r.owns(current));assertFalse(r.isClosed);assertFalse(r.propose(old,changed(p)));assertTrue(r.propose(current,changed(p)))}
 @Test fun closedReviewCannotOpenProposeOrApply(){val p=project();val r=VideoBatchReview(p.segments,p.soundtrack);val stage=Any();r.open(stage);r.dismiss(stage);assertTrue(r.isClosed);assertFalse(r.open(stage));assertFalse(r.propose(stage,changed(p)));assertFalse(r.apply(stage,p){});assertFalse(p.canUndo)}
 @Test fun baseAndProposalAreDefensiveAndImmutable(){val p=project();val raw=p.segments.toMutableList();val r=VideoBatchReview(raw,p.soundtrack);raw.clear();assertEquals(p.segments,r.base);try{(r.base as MutableList).clear();fail("Mutable base")}catch(_:UnsupportedOperationException){};val stage=Any();r.open(stage);val next=changed(p).toMutableList();assertTrue(r.propose(stage,next));next.clear();assertTrue(r.apply(stage,p){});assertEquals("Batch",p.segments[0].title)}
 @Test fun proposalCannotRetargetAndStageChangeDropsOldProposal(){val p=project();val r=VideoBatchReview(p.segments,p.soundtrack);val first=Any();val next=Any();r.open(first);assertTrue(r.propose(first,changed(p)));assertFalse(r.propose(first,p.segments.map{it.copy(title="Other")}));r.open(next);assertFalse(r.apply(next,p){});assertTrue(r.propose(next,changed(p)));assertTrue(r.apply(next,p){});assertEquals("Batch",p.segments[0].title)}
 @Test fun oneUseApplyPreservesMusicProvenanceAndOneUndo(){val p=project();val old=p.segments;val music=p.soundtrack;val r=VideoBatchReview(old,music);val s=Any();r.open(s);r.propose(s,changed(p));assertTrue(r.apply(s,p){});assertTrue(r.isClosed);assertFalse(r.apply(s,p){});assertSame(music,p.soundtrack);assertEquals(old[0].captionSourceUri,p.segments[0].captionSourceUri);assertTrue(p.undo());assertEquals(old,p.segments);assertFalse(p.canUndo);assertTrue(p.redo());assertEquals("Batch",p.segments[0].title)}
 @Test fun failedOwnerCheckConsumesApprovalBeforeMutation(){val p=project();val r=VideoBatchReview(p.segments,p.soundtrack);val s=Any();r.open(s);r.propose(s,changed(p));try{r.apply(s,p){error("Closed owner")};fail("Ignored guard")}catch(e:IllegalStateException){assertEquals("Closed owner",e.message)};assertTrue(r.isClosed);assertFalse(p.canUndo);assertFalse(r.apply(s,p){})}
 @Test fun staleProjectOrMusicConsumesWithoutAnotherEdit(){for(music in listOf(false,true)){val p=project();val r=VideoBatchReview(p.segments,p.soundtrack);val s=Any();r.open(s);r.propose(s,changed(p));if(music)p.setSoundtrack(p.soundtrack!!.copy(volume=.5f))else p.setTitle(0,"Changed");val before=p.segments;rejects{r.apply(s,p){}};assertTrue(r.isClosed);assertSame(before,p.segments)}}
 @Test fun noOpAndInvalidProjectFailureAreAtomicAndConsumed(){for(invalid in listOf(false,true)){val p=project();val old=p.segments;val r=VideoBatchReview(old,p.soundtrack);val s=Any();r.open(s);r.propose(s,if(invalid)listOf(old[0].copy(endMs=6000))else old);rejects{r.apply(s,p){}};assertTrue(r.isClosed);assertSame(old,p.segments);assertFalse(p.canUndo)}}
 private fun request(a:HonorableVideoEditorActivity,proposal:List<VideoSegment>?=null):Pair<VideoBatchReview,AlertDialog>{val p=get(a,"project")as VideoEditProject;val r=VideoBatchReview(p.segments,p.soundtrack);val d=dialog();r.open(d);r.propose(d,proposal?:changed(p));set(a,"batchReviewRequest",r);set(a,"batchReviewDialog",d);set(a,"captionReviewDialogs",linkedSetOf(d));return r to d}
 private fun commit(a:HonorableVideoEditorActivity,r:Pair<VideoBatchReview,AlertDialog>,review:VideoCaptionReviewState)=call(a,"commitBatchReview",r.second,r.first,review)as Boolean
 @Test fun pausedBatchMenuAndToolReturnBeforeWidgets(){val a=activity();set(a,"workspaceActive",false);call(a,"batchOptions");call(a,"batchEdit",VideoBatchTool.REVERSE);assertNull(get(a,"batchReviewRequest"));assertNull(get(a,"batchReviewDialog"))}
 @Test fun actualActivityApprovalUsesFrozenProposalOnce(){val a=activity();val p=get(a,"project")as VideoEditProject;val old=p.segments;val review=capture(a);val request=request(a);assertTrue(commit(a,request,review));assertTrue(request.first.isClosed);assertFalse(commit(a,request,review));assertEquals("Batch",p.segments[0].title);assertTrue(p.undo());assertEquals(old,p.segments);assertFalse(p.canUndo)}
 @Test fun oldStageCannotConsumeNewStageOfSameRequest(){val a=activity();val p=get(a,"project")as VideoEditProject;val review=capture(a);val old=request(a);val current=dialog();old.first.open(current);old.first.propose(current,changed(p));set(a,"batchReviewDialog",current);set(a,"captionReviewDialogs",linkedSetOf(current));assertFalse(commit(a,old,review));assertFalse(old.first.isClosed);assertTrue(old.first.owns(current));assertTrue(commit(a,old.first to current,review))}
 @Test fun foreignOldRequestCannotConsumeNewReview(){val a=activity();val review=capture(a);val old=request(a);val current=request(a);assertFalse(commit(a,old,review));assertSame(current.first,get(a,"batchReviewRequest"));assertFalse(current.first.isClosed);assertTrue(commit(a,current,review))}
 @Test fun currentDismissedDecorClosesOnlyItsOwnApproval(){val a=activity();val p=get(a,"project")as VideoEditProject;val review=capture(a);val request=request(a);showing(request.second,false);assertFalse(commit(a,request,review));assertTrue(request.first.isClosed);assertFalse(p.canUndo)}
 @Test fun untrackedCurrentDialogCannotCommit(){val a=activity();val p=get(a,"project")as VideoEditProject;val review=capture(a);val request=request(a);set(a,"captionReviewDialogs",linkedSetOf<AlertDialog>());assertFalse(commit(a,request,review));assertTrue(request.first.isClosed);assertFalse(p.canUndo)}
 @Test fun staleForegroundGenerationSourceDurationRangeRecoveryOrBusyRejects(){for(flag in listOf("pause","generation","source","duration","range","mode","recovery","busy")){val a=activity();val p=get(a,"project")as VideoEditProject;val review=capture(a);val request=request(a);when(flag){"pause"->set(a,"workspaceActive",false);"generation"->set(a,"captionReviewGeneration",review.generation+1);"source"->set(a,"source",Uri.parse("content://synthetic/other"));"duration"->set(a,"primaryDurationMs",6000L);"range"->set(a,"selectedClip",1);"mode"->set(a,"accessMode",EditorAccessMode.ACCOUNT);"recovery"->set(a,"recoveryBytes",byteArrayOf(1));else->set(a,"saving",true)};assertFalse(flag,commit(a,request,review));assertTrue(request.first.isClosed);assertFalse(p.canUndo)}}
 @Test fun undoCannotReviveConsumedApproval(){val a=activity();val p=get(a,"project")as VideoEditProject;val review=capture(a);val request=request(a);assertTrue(commit(a,request,review));assertTrue(p.undo());assertEquals(true,call(a,"canApplyCaptionReview",review));assertFalse(commit(a,request,review));assertFalse(p.canUndo);assertTrue(p.canRedo)}
 @Test fun establishedProposalAlgorithmsUseSameCommitBoundary(){for(kind in listOf("divide","case","title")){val a=activity();val p=get(a,"project")as VideoEditProject;val old=p.segments;val review=capture(a);val proposal=when(kind){"divide"->VideoBatchTools.divide(old,0,2);"case"->VideoRefinementTools.captionCase(old,0,CaptionLetterCase.LOWER);else->VideoAuthoringTools.storyboardTitles(old,"New title")};val request=request(a,proposal);assertTrue(kind,commit(a,request,review));assertEquals(proposal,p.segments);assertTrue(p.undo());assertEquals(old,p.segments);assertFalse(p.canUndo)}}
 @Test fun reviewInvalidationClosesRequestEvenWithoutLiveDialogCallbacks(){val a=activity();val request=request(a);val generation=get(a,"captionReviewGeneration")as Long;set(a,"captionReviewDialogs",linkedSetOf<AlertDialog>());call(a,"invalidateCaptionReviews");assertTrue(request.first.isClosed);assertNull(get(a,"batchReviewRequest"));assertNull(get(a,"batchReviewDialog"));assertEquals(generation+1,get(a,"captionReviewGeneration"))}
}
